INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37011, 'Matthew 5:35', 'Matthew', 5, 35, 'نه په ځمکه ځکه چې دا د هغه د پښو ایښودلو چوکۍ ده، نه په اورشلیم ځکه چې دا د لوی پاچا ښار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_35.mp3', '', 1761754199, 1761754199),
(37012, 'Matthew 5:36', 'Matthew', 5, 36, 'همدارنګه په خپل سر قسم مه خورئ، ځکه چې تاسو نه شئ کولای د هغه یو ویښته هم تور یا سپین کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_36.mp3', '', 1761754199, 1761754199),
(37013, 'Matthew 5:37', 'Matthew', 5, 37, 'ستاسو ‹هو› دې ‹هو› وي او ‹نه› مو ‹نه› وي. د دې نه زیات د شیطان کار دی. د بدل نه اخیستلو په هکله تعلیم (لوقا ۶‏:‌۲۹‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_37.mp3', '', 1761754199, 1761754199),
(37014, 'Matthew 5:38', 'Matthew', 5, 38, 'تاسو اورېدلي دي چې ویل شوي دي: ‹د سترګې په بدل کې سترګه او د غاښ په بدل کې غاښ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_38.mp3', '', 1761754199, 1761754199),
(37015, 'Matthew 5:39', 'Matthew', 5, 39, 'خو زه تاسو ته وایم څوک چې درسره بدي کوي، نو ته ترې بدل مه اخله. که څوک درته په ښي مخ څپېړه درکړي، نو چپ مخ دې هم ورته ورواړوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_39.mp3', '', 1761754199, 1761754199),
(37016, 'Matthew 5:40', 'Matthew', 5, 40, 'که چېرې څوک ستا په کمیس باندې دعوه وکړي نو خپله چپنه هم ورته ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_40.mp3', '', 1761754199, 1761754199),
(37017, 'Matthew 5:41', 'Matthew', 5, 41, 'که چېرې څوک تا دې ته مجبور کړي چې یونیم کیلومتر ورسره لاړ شې، نو درې کیلومتره ورسره لاړ شه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_41.mp3', '', 1761754199, 1761754199),
(37018, 'Matthew 5:42', 'Matthew', 5, 42, 'که څوک درڅخه کوم څه وغواړي نو هغه ورته ورکړه او څوک چې درڅخه پور غواړي، نو انکار ورته مه کوه. د دښمن سره مینه کول (لوقا ۶‏:‌۲۷‌‏-‌۲۸، ۶‏:‌۳۲‌‏-‌۳۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_42.mp3', '', 1761754199, 1761754199),
(37019, 'Matthew 5:43', 'Matthew', 5, 43, 'تاسو اورېدلي چې ویل شوي دي: ‹د خپلو ګاونډیانو سره مینه کوه او د خپل دښمن څخه کرکه کوه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_43.mp3', '', 1761754199, 1761754199),
(37020, 'Matthew 5:44', 'Matthew', 5, 44, 'خو زه تاسو ته وایم چې د خپلو دښمنانو سره مینه کوئ او څوک چې تاسو ځوروي، د هغوی دپاره دعا کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_44.mp3', '', 1761754199, 1761754199),
(37021, 'Matthew 5:45', 'Matthew', 5, 45, 'نو په دې به تاسو د خپل اسماني پلار اولادونه شئ، ځکه چې هغه په بدو او ښو خلکو باندې یوشان لمر راخېژوي او په نېکو او بدو خلکو باندې یوشان باران وروي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_45.mp3', '', 1761754199, 1761754199),
(37022, 'Matthew 5:46', 'Matthew', 5, 46, 'که تاسو یوازې د هغو خلکو سره مینه کوئ چې ستاسو سره مینه کوي، نو په دې کې به تاسو ته څه اجر وي؟ ایا مالیه ټولوونکي همداسې نه کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_46.mp3', '', 1761754199, 1761754199),
(37023, 'Matthew 5:47', 'Matthew', 5, 47, 'که چېرې تاسو یوازې په خپلو ورونو سلام اچوئ، نو د نورو سره ستاسو فرق څه دی؟ ایا کافران همداسې نه کوي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_47.mp3', '', 1761754199, 1761754199),
(37024, 'Matthew 5:48', 'Matthew', 5, 48, 'نو تاسو باید کامل اوسئ لکه څنګه چې ستاسو اسماني پلار کامل دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew5_verse_48.mp3', '', 1761754199, 1761754199),
(37025, 'Hebrews 5:1', 'Hebrews', 5, 1, 'هر لوی کاهن د خلکو له منځ نه د دې دپاره ټاکل کیږي چې د خدای په حضور کې د خلکو استازیتوب وکړي او د انسانانو د ګناهونو دپاره نذرانې او قربانۍ وړاندې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_1.mp3', '', 1761754199, 1761754199),
(37026, 'Hebrews 5:2', 'Hebrews', 5, 2, 'هغه کولای شي چې د ناپوهو او بې‌لارې خلکو سره په نرمۍ چلند وکړي، ځکه چې هغه په خپله د کمزورتیاوو سره مخ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_2.mp3', '', 1761754199, 1761754199),
(37027, 'Hebrews 5:3', 'Hebrews', 5, 3, 'له همدې امله هغه مجبور دی چې یوازې د خلکو د ګناهونو دپاره نه بلکې د خپل ځان د ګناهونو دپاره هم قرباني وړاندې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_3.mp3', '', 1761754199, 1761754199),
(37028, 'Hebrews 5:4', 'Hebrews', 5, 4, 'هېڅوک نه شي کولای چې د خپل ځان دپاره دا عزت حاصل کړي چې کاهن شي، بلکې هغه باید د خدای له خوا وغوښتل شي لکه څنګه چې هارون وغوښتل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_4.mp3', '', 1761754199, 1761754199),
(37029, 'Hebrews 5:5', 'Hebrews', 5, 5, 'په همدې ډول مسیح هم د لوی کاهن عزت په خپله حاصل نه کړ، بلکې هغه د خدای له خوا وټاکل شو چې ورته ویې ویل: ته مې زوی، زه دې نن پلار شوم', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_5.mp3', '', 1761754199, 1761754199),
(37030, 'Hebrews 5:6', 'Hebrews', 5, 6, 'همدارنګه هغه په بل ځای کې وایي: ته به کاهن یې تر ابده د ملک‌صدق په شان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_6.mp3', '', 1761754199, 1761754199),
(37031, 'Hebrews 5:7', 'Hebrews', 5, 7, 'کله چې عیسی د ځمکې په مخ ژوند کاوه، نو په ډېرو چیغو او اوښکو تویولو سره خدای ته چې په دې قادر ؤ هغه د مرګ نه وژغوري، دعاګانې او زارۍ وکړې او دعاګانې یې قبولې شوې، ځکه چې هغه په پوره توګه خپل ځان خدای ته سپارلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_7.mp3', '', 1761754199, 1761754199),
(37032, 'Hebrews 5:8', 'Hebrews', 5, 8, 'که څه هم هغه د خدای زوی ؤ، خو د دردونو او کړاوونو په زغملو سره یې اطاعت کول زده کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_8.mp3', '', 1761754199, 1761754199),
(37033, 'Hebrews 5:9', 'Hebrews', 5, 9, 'کله چې هغه کامل کړای شو، نو د هغو ټولو خلکو دپاره د ابدي خلاصون سرچینه شوه چې د ده اطاعت کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_9.mp3', '', 1761754199, 1761754199),
(37034, 'Hebrews 5:10', 'Hebrews', 5, 10, 'او هغه د خدای له خوا د ملک‌صدق په شان لوی کاهن وټاکل شو. د ایماندارانو روحاني پوخوالی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_10.mp3', '', 1761754199, 1761754199),
(37035, 'Hebrews 5:11', 'Hebrews', 5, 11, 'په دې هکله زمونږ سره د ویلو دپاره ډېرې خبرې شته، خو ډېره سخته ده چې تاسو ته بیان شي، ځکه چې تاسو په هغو باندې د پوهېدلو کوښښ نه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_11.mp3', '', 1761754199, 1761754199),
(37036, 'Hebrews 5:12', 'Hebrews', 5, 12, 'دا وخت باید تاسو استاذان وئ، خو اوس هم یو کس ته اړتیا لرئ چې تاسو ته د خدای د کلام بنیادي اصول درزده کړي. تاسو د ماشومانو په شان شیدو ته اړتیا لرئ، نه قوي خوړو ته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_12.mp3', '', 1761754199, 1761754199),
(37037, 'Hebrews 5:13', 'Hebrews', 5, 13, 'ځکه چې هرڅوک چې یوازې شیدې خوري، هغه لا ماشوم دی او په ښو او بدو نه پوهیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_13.mp3', '', 1761754199, 1761754199),
(37038, 'Hebrews 5:14', 'Hebrews', 5, 14, 'خو قوي خواړه د بالغو او پخو خلکو دپاره دي چې د روزنې او تمرین له لارې کولای شي چې د ښو او بدو ترمنځ فرق وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews5_verse_14.mp3', '', 1761754199, 1761754199),
(37039, 'Psalms 34:1', 'Psalms', 34, 1, 'تل به کومه د څښتن ثنا او صفت وي به همېش زما په شونډو د هغه ستاینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_1.mp3', '', 1761754199, 1761754199),
(37040, 'Psalms 34:2', 'Psalms', 34, 2, 'زه به یې وستایم په هغه چې یې کړي دي څه پرېږده ټول بې‌وزلي واوري او خوشحال شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_2.mp3', '', 1761754199, 1761754199),
(37041, 'Psalms 34:3', 'Psalms', 34, 3, 'د څښتن لویي زما سره اعلان کړئ راشئ یوځای یې د نوم ستاینه وکړو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_3.mp3', '', 1761754199, 1761754199),
(37042, 'Psalms 34:4', 'Psalms', 34, 4, 'ما دعا وکړه څښتن ته او هغه کړله قبوله زه یې کړم خلاص د ټولو وېرو ځینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_4.mp3', '', 1761754199, 1761754199),
(37043, 'Psalms 34:5', 'Psalms', 34, 5, 'څوک چې توکل کړي په هغه نو د خوشحالۍ نه به یې ځلیږي مخ هغوی به هېڅکله ونه شرمیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_5.mp3', '', 1761754199, 1761754199),
(37044, 'Psalms 34:6', 'Psalms', 34, 6, 'دې بې‌وزله سړي وکړلو فریاد څښتن ځواب کړ هغه خلاص کړلو د خپلو ټولو تکلیفونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_6.mp3', '', 1761754199, 1761754199),
(37045, 'Psalms 34:7', 'Psalms', 34, 7, 'هغه خلک چې د څښتن څخه کړي وېره فرښته وي د څښتن د داسې خلکو نه چاپېره او خلاصون ورکوي دوی ته له خطره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_7.mp3', '', 1761754199, 1761754199),
(37046, 'Psalms 34:8', 'Psalms', 34, 8, 'ګورئ ځان پوه کړئ چې څښتن دی څومره غوره بختور دي هغه څوک چې د هغه نه پناه غواړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_8.mp3', '', 1761754199, 1761754199),
(37047, 'Psalms 34:9', 'Psalms', 34, 9, 'وېره وکړئ له څښتنه د څښتن سپېڅلو خلکو محتاج به نه وي هغه خلک چې کړي د ده نه وېره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_9.mp3', '', 1761754199, 1761754199),
(37048, 'Psalms 34:10', 'Psalms', 34, 10, 'د لوږې او احتیاج نه زمریان هم ځوریږي خو هغه چې رجوع وکړي څښتن ته د هغوی دپاره نه به وي کمی د نعمتونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_10.mp3', '', 1761754199, 1761754199),
(37049, 'Psalms 34:11', 'Psalms', 34, 11, 'راشئ، بچیانو ماته غوږ ونیسئ چې د څښتن عزت کول درزده کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_11.mp3', '', 1761754199, 1761754199),
(37050, 'Psalms 34:12', 'Psalms', 34, 12, 'ایا د ژوند خوند اخیستل غواړئ؟ ایا خوشحاله اوږد ژوندون غواړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_12.mp3', '', 1761754199, 1761754199),
(37051, 'Psalms 34:13', 'Psalms', 34, 13, 'وساتئ خپله ژبه بدو خبرو نه وساتئ خپلې شونډې د دروغو نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_13.mp3', '', 1761754199, 1761754199),
(37052, 'Psalms 34:14', 'Psalms', 34, 14, 'له بدو لېرې ګرځئ کوئ نېکي سولې دپاره هلې‌ځلې کوئ او ورپسې وګرځئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_14.mp3', '', 1761754199, 1761754199),
(37053, 'Psalms 34:15', 'Psalms', 34, 15, 'دی د څښتن نظر نېکانو باندې او نیسي غوږ یې فریادونو لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_15.mp3', '', 1761754199, 1761754199),
(37054, 'Psalms 34:16', 'Psalms', 34, 16, 'خو دی څښتن د بدکارانو خلاف او ورکوي د ځمکې د مخ نه د هغوی نوم او نښان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_16.mp3', '', 1761754199, 1761754199),
(37055, 'Psalms 34:17', 'Psalms', 34, 17, 'نېکان فریاد کوي څښتن ته او هغه یې اوري دوی خلاصوي له خپلو ټولو تکلیفونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_17.mp3', '', 1761754199, 1761754199),
(37056, 'Psalms 34:18', 'Psalms', 34, 18, 'څښتن نژدې دی هغو خلکو ته چې زړونه یې مات وي ورکوي نجات هغو ته چې بایللی یې امید وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_18.mp3', '', 1761754199, 1761754199),
(37057, 'Psalms 34:19', 'Psalms', 34, 19, 'ډېر تکلیفونه په نېک شخص راځي خو هغو ټولو نه څښتن دا ژغوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_19.mp3', '', 1761754199, 1761754199),
(37058, 'Psalms 34:20', 'Psalms', 34, 20, 'هغه ساتي ټول هډوکي د ده هېڅ یو ماتیږي نه له هغو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_20.mp3', '', 1761754199, 1761754199),
(37059, 'Psalms 34:21', 'Psalms', 34, 21, 'خپلې بدۍ له لاسه مړه به شي بدکاره خلک سزا به ورکړل شي هغو ته چې کړي کرکه د نېکانو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_21.mp3', '', 1761754199, 1761754199),
(37060, 'Psalms 34:22', 'Psalms', 34, 22, 'څښتن نجات ورکوي خپلو بندګانو لره څوک چې هغه ته پناه یوسي نو مجرم به نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms34_verse_22.mp3', '', 1761754199, 1761754199),
(37061, 'Numbers 28:1', 'Numbers', 28, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_1.mp3', '', 1761754199, 1761754199),
(37062, 'Numbers 28:2', 'Numbers', 28, 2, '«دا حکم د اسراییلو قوم ته ورسوه او هغوی ته ووایه: ‹ماته به په ټاکلي وخت کې د نذرانو په خاطر هغه خواړه وړاندې کوئ چې په اور باندې تیاریږي. د داسې نذرانې بوی په ما باندې ښه لګیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_2.mp3', '', 1761754199, 1761754199),
(37063, 'Numbers 28:3', 'Numbers', 28, 3, 'دا هغه نذرانې دي چې په اور باندې تیاریږي او باید څښتن ته د ورځنۍ سوځېدونکې نذرانې دپاره وړاندې شي: دوه یو کلن وري چې هېڅ عیب په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_3.mp3', '', 1761754199, 1761754199),
(37064, 'Numbers 28:4', 'Numbers', 28, 4, 'یو وری به په سهار کې قرباني کیږي او بل په ماښام کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_4.mp3', '', 1761754199, 1761754199),
(37065, 'Numbers 28:5', 'Numbers', 28, 5, 'هر وری باید د یو کیلو ګرام ښو اوړو سره چې یو لیتر د زیتونو سوچه تېل ورسره ګډ وي د غلې دانې د نذرانې په توګه وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_5.mp3', '', 1761754199, 1761754199),
(37066, 'Numbers 28:6', 'Numbers', 28, 6, 'دا هغه ورځنۍ سوځېدونکې نذرانه ده چې د اول ځل دپاره د سینا د غره په څنګ کې څښتن ته د یوې خوشحالوونکې خوشبویۍ په توګه وړاندې شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_6.mp3', '', 1761754199, 1761754199),
(37067, 'Numbers 28:7', 'Numbers', 28, 7, 'په اخر کې د دغو دوو نذرانو سره یو یو لیتر شراب د څښلو د نذرانې په توګه باید څښتن ته د قربانۍ په ځای باندې توی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_7.mp3', '', 1761754199, 1761754199),
(37068, 'Numbers 28:8', 'Numbers', 28, 8, 'دوهم وری په ماښام کې د غلې دانې او څښلو د هماغه شان نذرانې سره تیار کړئ چې تاسو یې په سهار کې تیاروئ. دا یوه داسې نذرانه ده چې په اور باندې تیاریږي او یو داسې بوی دی چې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_8.mp3', '', 1761754199, 1761754199),
(37069, 'Numbers 28:11', 'Numbers', 28, 11, 'د هرې میاشتې په لومړۍ ورځ دوه خوسیان، یو پسه او اووه یو کلن وري چې په ټولو کې هېڅ عیب نه وي، څښتن ته د سوځېدونکې نذرانې دپاره وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_11.mp3', '', 1761754199, 1761754199),
(37070, 'Numbers 28:12', 'Numbers', 28, 12, 'درې کیلو ګرامه ښه اوړه چې د زیتونو تېل ورسره ګډ وي باید د هر غویي سره د غلې دانې د نذرانې په توګه وړاندې شي. دوه کیلو ګرامه اوړه چې تېل ورسره ګډ وي باید د پسه سره وړاندې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_12.mp3', '', 1761754199, 1761754199),
(37071, 'Numbers 28:13', 'Numbers', 28, 13, 'او یو کیلو ګرام اوړه چې تېل ورسره ګډ وي باید د هر وري سره وړاندې شي. دا د سوځېدونکې نذرانې دپاره دي، دا یوه داسې نذرانه ده چې بوی یې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_13.mp3', '', 1761754199, 1761754199),
(37072, 'Numbers 28:16', 'Numbers', 28, 16, 'د هر کال د اولې میاشتې په څوارلسمه ورځ څښتن ته د درناوي په خاطر د فسحې اختر لمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_16.mp3', '', 1761754199, 1761754199),
(37073, 'Numbers 28:17', 'Numbers', 28, 17, 'په پنځلسمه ورځ به د فطیرې ډوډۍ اختر وي چې یوه هفته به دوام ومومي. په دې دوران کې باید فطیره ډوډۍ وخوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_17.mp3', '', 1761754199, 1761754199),
