(37077, 'Numbers 28:21', 'Numbers', 28, 21, 'او یو کیلو ګرام اوړه چې تېل ورسره ګډ وي باید د هر وري سره وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_21.mp3', '', 1761754199, 1761754199),
(37078, 'Numbers 28:22', 'Numbers', 28, 22, 'همدارنګه یو سېرلی د ګناه د نذرانې په توګه وړاندې کړئ او په دې ډول د قوم دپاره کفاره ادا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers28_verse_22.mp3', '', 1761754199, 1761754199),
