(37088, 'Psalms 61:1', 'Psalms', 61, 1, 'زما فریاد واوره ای خدایه کړه قبوله مې دعا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms61_verse_1.mp3', '', 1761754199, 1761754199),
(37089, 'Psalms 61:2', 'Psalms', 61, 2, 'د اخر سر نه د دنیا درته نارې وهمه داسې حال کې چې مې زړه دی نا‌امیده زما نه اوچت ګټ ته مې بوځه ماته راکړه پناه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms61_verse_2.mp3', '', 1761754199, 1761754199),
(37090, 'Psalms 61:3', 'Psalms', 61, 3, 'ځکه زما د دښمنانو مقابل کې ته پناه ځای یې زما هم قوي برج یې زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms61_verse_3.mp3', '', 1761754199, 1761754199),
(37091, 'Psalms 61:4', 'Psalms', 61, 4, 'پرېږده چې واوسم ټول عمر ستا سپېڅلي ځای کې پرېږده چې اوسم سلامت ستا د وزرونو لاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms61_verse_4.mp3', '', 1761754199, 1761754199),
(37092, 'Psalms 61:5', 'Psalms', 61, 5, 'ای خدایه، ما چې کوم نذرونه دي ورکړي تا قبول کړي هغه تا راته هغه برکت راکړی چې دې ورکړی دی هغوی ته چې وېریږي ستا له نومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms61_verse_5.mp3', '', 1761754199, 1761754199),
