(37095, 'Psalms 61:8', 'Psalms', 61, 8, 'نو زه به تل ستا د ثنا سندرې وایم لکه چې څنګه ورکومه هره ورځ نذرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms61_verse_8.mp3', '', 1761754199, 1761754199),
(37096, 'Ezra 2:1', 'Ezra', 2, 1, 'ډېرو جلاوطنو خلکو د بابل ولایت پرېښود او اورشلیم او یهودا ته یعنې خپلو ښارګوټو ته راستانه شول. له هغه وخت څخه چې نبوکدنصر پاچا هغوی د اسیرانو په توګه بابل ته بېولي وو، د هغوی کورنۍ هلته په جلاوطنۍ کې اوسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_1.mp3', '', 1761754199, 1761754199),
(37097, 'Ezra 2:2', 'Ezra', 2, 2, 'دا د هغوی مشران وو: زروبابل، یشوع، نحمیا، سرایا، رعیلایا، مردخای، بلشان، مسفار، بغوای، رحوم او بعنه. دا د اسراییلو د طایفو لست دی چې په هغه کې د هرې طایفې د خلکو شمېر لیکل شوی دی چې د جلاوطنۍ څخه راستانه شوي وو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_2.mp3', '', 1761754199, 1761754199),
(37098, 'Ezra 2:58', 'Ezra', 2, 58, 'د خدای د کور د خدمتګارانو او د سلیمان د خدمتګارانو د اولادې ټول شمېر چې د جلاوطنۍ څخه راستانه شوي وو، ۳۹۲ تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_58.mp3', '', 1761754199, 1761754199),
(37099, 'Ezra 2:63', 'Ezra', 2, 63, 'د یهودیانو والي هغوی ته وویل: «تر هغې پورې چې د کوم کاهن له خوا د اوریم او تمیم په وسیله معلومه نه شي چې تاسو په رښتیا سره کاهنان یئ، تاسو نه شئ کولای هغه ډوډۍ وخورئ چې خدای ته وړاندې کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_63.mp3', '', 1761754199, 1761754199),
(37100, 'Ezra 2:68', 'Ezra', 2, 68, 'کله چې جلاوطني خلک په اورشلیم کې هغه ځای ته ورسېدل چې پخوا په کې د څښتن کور ؤ، نو د طایفو ځینو مشرانو د خپلې خوښې نذرانې ورکړې چې په خپل پخواني ځای کې د خدای د کور په بیا جوړولو کې د هغه څخه کار واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_68.mp3', '', 1761754199, 1761754199),
(37101, 'Ezra 2:69', 'Ezra', 2, 69, 'هغوی د دې کار دپاره د خپل توان سره سم پنځه سوه کیلو ګرامه سره زر، دوه زره اته سوه کیلو ګرامه سپین زر او د کاهنانو دپاره یې سل دانې چپنې خزانې ته ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_69.mp3', '', 1761754199, 1761754199),
(37102, 'Ezra 2:70', 'Ezra', 2, 70, 'کاهنان، لاویان او ځینې نور خلک په اورشلیم کې یا د اورشلیم سره نژدې ځای په ځای شول. سندرغاړي، د خدای د کور ساتونکي او خدمتګاران په نژدې ښارګوټو کې ځای په ځای شول او پاتې اسراییلیان په هغو ښارګوټو کې ځای په ځای شول چې د هغوی نیکونه په کې اوسېدلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra2_verse_70.mp3', '', 1761754199, 1761754199),
(37103, 'Zechariah 4:1', 'Zechariah', 4, 1, 'بيا کومې فرښتې چې ما سره خبرې کولې ما له بيا راغله او زۀ يې بېدار کړم، لکه څنګه چې يو سړے د خوب نه راپاڅوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_1.mp3', '', 1761754199, 1761754199),
(37104, 'Zechariah 4:2', 'Zechariah', 4, 2, '”اوس تا ته څۀ ښکارى؟“ هغې ما نه تپوس وکړو. ما جواب ورکړو، ”زۀ د سرو زرو يو ډيوټ ګورم چې په سر يې د تېلو يوه کاسه ده. او د کاسې نه ګېرچاپېره اووۀ ډيوې دى، او د هرې يوې د باتو سره اووۀ د تېلو فوارې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_2.mp3', '', 1761754199, 1761754199),
(37105, 'Zechariah 4:3', 'Zechariah', 4, 3, 'هم دې سره خوا ته دوه د زيتُونو ونې دى، يو د جام ښى طرف ته او بله ګس طرف ته ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_3.mp3', '', 1761754199, 1761754199),
(37106, 'Zechariah 4:4', 'Zechariah', 4, 4, 'ما د فرښتې نه تپوس وکړو چا چې ما سره خبرې کولې، ”دا څۀ دى، زما مالِکه؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_4.mp3', '', 1761754199, 1761754199),
(37107, 'Zechariah 4:5', 'Zechariah', 4, 5, 'هغې ما ته جواب راکړو، ”آيا تا ته پته نشته چې دا څۀ دى؟“ ”نه، زما مالِکه،“ ما جواب ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_5.mp3', '', 1761754199, 1761754199),
(37108, 'Zechariah 4:6', 'Zechariah', 4, 6, 'نو هغه فرښتې ما ته وفرمائيل، ”دا زرُبابل ته د مالِک خُدائ کلام دے، نۀ په طاقت او نۀ په قدرت، خو زما په روح باندې، مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_6.mp3', '', 1761754199, 1761754199),
(37109, 'Zechariah 4:7', 'Zechariah', 4, 7, 'هيڅ څيز هم نه، تر دې چې د زرُبابل په لار کښې غټ غرونه هم نۀ شى ودرېدلے، دا به د هغۀ په وړاندې هوار کړے شى. او کله چې زرُبابل د خُدائ د کور آخرى کاڼے په خپل ځائ کښې ږدى، خلق به چغې ووهى، خُدائ دې برکت ورکړى. خُدائ دې برکت ورکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_7.mp3', '', 1761754199, 1761754199),
(37110, 'Zechariah 4:8', 'Zechariah', 4, 8, 'بيا د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_8.mp3', '', 1761754199, 1761754199);